int main() {
    int n;
    int minValue = 10000009;
    // 记录异或计算结果
    int sum = 0;
    // 记录实际重量和
    int totalWeight = 0;
    cin >> n;
    for (int i = 0; i < n; i++) {
        int tmp;
        cin >> tmp;
        sum ^= tmp;
        minValue = min(minValue, tmp);
        totalWeight += tmp;
    }
    // 不能平分
    if (sum != 0) {
        cout << "NO";
    } else {
        cout << totalWeight - minValue;
    }
    return 0;
}

