​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
let inputLines = [];
rl.on('line', line => {
    inputLines.push(line.trim());
});
​
rl.on('close', () => {
    const n = parseInt(inputLines[0]);
    const arr = inputLines[1].split(' ').map(Number);
​
    let sum = 0; // 异或和
    let totalWeight = 0; // 总重量
    let minValue = Infinity; // 最小值
​
    for (let num of arr) {
        sum ^= num;
        totalWeight += num;
        minValue = Math.min(minValue, num);
    }
​
    if (sum !== 0) {
        console.log("NO");
    } else {
        console.log(totalWeight - minValue);
    }
});
