package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
​
    // 读取 n
    line, _ := reader.ReadString('\n')
    n, _ := strconv.Atoi(strings.TrimSpace(line))
​
    // 读取数组
    line, _ = reader.ReadString('\n')
    parts := strings.Fields(line)
​
    sum := 0               // 异或和
    totalWeight := 0       // 总重量
    minValue := 1000000009 // 重量最小值
​
    for i := 0; i < n; i++ {
        num, _ := strconv.Atoi(parts[i])
        sum ^= num
        totalWeight += num
        if num < minValue {
            minValue = num
        }
    }
​
    if sum != 0 {
        fmt.Println("NO")
    } else {
        fmt.Println(totalWeight - minValue)
    }
}
